// User-facing text generated by the model (risks, tasks, observations).
//
// The model logic in plan.ts is language-neutral: rules, ids, priorities,
// ordering and numbers never depend on the language. Only the strings below do.
// English is canonical (result snapshots are stored in English); German is the
// display variant. Plain business German, formal "Sie". Statements reflect what
// the user reported; they never imply verification, valuation, or a legal or
// tax conclusion.

import type { Lang } from '../lib/i18n';
import type { Horizon } from './types';

export interface ModelText {
  risk: {
    acuteTitle: string; acuteText: string;
    liqTitle: string; liqUnknown: string; liqPotential: string;
    r02Title: string; r02Text: string; r02OpenTitle: string; r02OpenText: string;
    r03Title: string; r03Text: string; r03OpenTitle: string; r03OpenText: string;
    r04Title: string; r04Text: string;
    r05Title: string; r05Text: string;
    r06Title: string; r06Text: string;
    r07Title: string; r07Text: string;
    appTitle: (route: string) => string;
    appText: (route: string) => string;
  };
  task: {
    reconfirm: string; clarify: string; critical: string; needsReview: string;
    gap: string; partial: string; unanswered: string; adviserReview: string; confirm: string;
    reconfirmAction: string; clarifyAction: string; specialistAction: string;
    transactionLead: string; specialistRole: string;
    gapReason: (today: string, target: string) => string;
    unansweredReason: string; reconfirmReason: string;
    markedReason: (statusLabel: string) => string;
  };
  timing: Record<Horizon, [string, string, string]>;
  obs: {
    continuity: string; continuityText: string;
    strengths: string; strengthsText: (strengths: string[]) => string;
    leadership: string; leadershipText: string;
    decisions: string; decisionsText: (employed: boolean) => string;
    expertise: string; expertiseText: string;
    customers: string; customersText: string;
    tax: string; taxText: string;
    proposition: string; propositionText: string;
    more: string; moreText: string;
  };
}

